inner='''<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="PREFIX-original.css"><a class="skip" href="#main">본문으로 건너뛰기</a><div id="app"></div><input id="file-open" type="file" accept=".json,application/json"><div id="dialog-host"></div><div id="toast-host" role="status" aria-live="polite"></div><div id="announcer" class="sr" role="status" aria-live="polite"></div><script src="PREFIX-original.js"></script><script>
const q=new URLSearchParams(location.search);let initialPage,initialFocus,initialHeading;
const box=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};
const target=()=>{const screen=q.get('screen');return screen==='home'?document.querySelector('[data-action="start"]'):screen==='capabilities'?document.querySelector('[data-action="permissions"]'):screen==='review'?document.querySelector('[data-flag="stopped"]'):screen==='running'?document.querySelector('[data-action="cancel"]'):screen==='results'?document.querySelector('[data-action="filter:all"]'):document.querySelector('[data-format="json"]')};
window.seedParentResize=async()=>{state=initial();lang=q.get('lang');state.run=makeRun(true);state.run.id='UI-PARENTRESIZE';if(q.get('screen')!=='running'){state.run.groups.forEach(completeGroup);state.run.complete=true}state.visited=new Set(['results','save']);go('results');go(q.get('screen'));await document.fonts.ready;await new Promise(r=>setTimeout(r,360));await Promise.all(document.querySelector('.page').getAnimations().map(a=>a.finished.catch(()=>{})));initialPage=document.querySelector('.page');initialHeading=document.getElementById('screen-title');initialFocus=target();if(!initialFocus||initialFocus.disabled)throw Error('Exact enabled parent focus seed required');initialFocus.focus({preventScroll:true});document.getElementById('main').scrollTop=0};
const textLayout=e=>{if(!e)return null;const st=getComputedStyle(e),lines=[];const walker=document.createTreeWalker(e,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){for(let i=0;i<node.textContent.length;i++){const r=document.createRange();r.setStart(node,i);r.setEnd(node,i+1);const rect=r.getBoundingClientRect();if(!rect.width&&!rect.height)continue;let line=lines.find(l=>Math.abs(l.y-rect.y)<.01);if(!line){line={y:rect.y,height:rect.height,x:rect.x,right:rect.right,text:''};lines.push(line)}line.text+=node.textContent[i];line.x=Math.min(line.x,rect.x);line.right=Math.max(line.right,rect.right)}}return{text:e.textContent,box:box(e),font:st.font,lineHeight:st.lineHeight,whiteSpace:st.whiteSpace,computedWidth:st.width,paddingLeft:st.paddingLeft,paddingRight:st.paddingRight,borderLeft:st.borderLeftWidth,borderRight:st.borderRightWidth,boxSizing:st.boxSizing,lines:lines.map(l=>({...l,width:l.right-l.x}))}};
window.headerPrecision=()=>{const original=document.querySelector('.capability-table th:nth-child(3)'),st=getComputedStyle(original),text=original.textContent,canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');ctx.font=st.font;const rows=[];for(const width of [80.4296875,80.421875,80.4375,80.4140625,80.4453125]){const e=document.createElement('div');e.style.cssText='position:fixed;left:0;top:0;display:block;opacity:0;overflow:visible;white-space:normal';e.style.font=st.font;e.style.letterSpacing=st.letterSpacing;e.style.width=width+'px';e.textContent=text;document.body.append(e);rows.push({width,computedWidth:getComputedStyle(e).width,layout:textLayout(e),canvas:{font:ctx.font,width:ctx.measureText(text).width,actualBoundingBoxLeft:ctx.measureText(text).actualBoundingBoxLeft,actualBoundingBoxRight:ctx.measureText(text).actualBoundingBoxRight}});e.remove()}return{original:textLayout(original),rows}};
const tableDiagnostics=()=>{const t=document.querySelector('.capability-table');if(!t)return null;return{box:box(t),header:{box:box(t.tHead),labels:[...t.tHead.rows[0].cells].map(textLayout)},rows:[...t.tBodies[0].rows].map((r,i)=>({key:categoryDefs.filter(c=>c.key!=='trial')[i].key,box:box(r),cells:[...r.cells].map(box),title:textLayout(r.cells[0].querySelector('strong')),description:textLayout(r.cells[0].querySelector('small')),details:textLayout(r.cells[3].querySelector('.capability-details>span')),permissions:box(r.querySelector('[data-action=permissions]'))}))}};
window.observeParentResize=async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const page=document.querySelector('.page'),focus=target(),summary=document.querySelector('.summary-item');return{width:innerWidth,height:innerHeight,pageSame:page===initialPage,headingSame:document.getElementById('screen-title')===initialHeading,focusTargetSame:focus===initialFocus,focusTargetFocused:document.activeElement===initialFocus,selected:initialFocus.matches('input[type=checkbox]')?initialFocus.checked:initialFocus.classList.contains('selected'),screen:state.screen,english:lang==='en',announcement:document.getElementById('announcer').textContent,pageOpacity:Number(getComputedStyle(page).opacity),pageAnimations:page.getAnimations().filter(a=>a.playState==='running').length,mainScroll:document.getElementById('main').scrollTop,documentScroll:{x:scrollX,y:scrollY},boxes:{topbar:box(document.querySelector('.topbar')),content:box(document.getElementById('main')),page:box(page),heading:box(document.querySelector('.page-heading')),focus:box(focus),footer:box(document.querySelector('.footer')),summaryLabel:box(summary?.children[0]),summaryValue:box(summary?.children[1]),metrics:box(document.querySelector('.metrics'))},footerActions:[...document.querySelectorAll('.footer [data-action]')].map(e=>({action:e.dataset.action,disabled:e.disabled})),formats:[...state.formats],stopped:state.stopped,visited:[...state.visited].sort(),root:{clientWidth:document.documentElement.clientWidth,clientHeight:document.documentElement.clientHeight,scrollWidth:document.documentElement.scrollWidth,scrollHeight:document.documentElement.scrollHeight},tableDiagnostics:q.get('debug')==='table'?tableDiagnostics():undefined,scope:'CSS resize only; synthetic pending Progress with no interval, programmatic focus setup only'};};
</script>'''.replace('PREFIX',prefix)
(out/f'{prefix}-inner.html').write_text(inner)
