script='''const q=new URLSearchParams(location.search);window.recordParentResize=async()=>{const records=[];for(const f of document.querySelectorAll('iframe')){if(q.get('context')&&f.title!==q.get('context'))continue;if(q.get('debug')==='table'){const inner=new URL(f.src);inner.searchParams.set('debug','table');f.src=inner.href;await new Promise(resolve=>f.addEventListener('load',resolve,{once:true}))}f.style.visibility='visible';f.width=1280;f.style.width='1280px';await f.contentWindow.seedParentResize();const rows=[];for(const width of (q.get('debug')==='table'?[1280,1100]:[1280,1100,960,1280])){f.width=width;f.style.width=width+'px';rows.push(await f.contentWindow.observeParentResize())}records.push({id:f.title,rows});f.style.visibility='hidden'}const os=q.get('os')==='windows'?'windows':'mac';const result={recording:q.get('recording'),scope:'parent-resize-only6',dpr:devicePixelRatio,originalHashes:HASHES,rows:records};const response=await fetch('/evidence/connection-pageintegrationparentresize-'+os+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(result)});if(!response.ok)throw Error('Owned parent resize record failed');document.title='Parent resize recorded · original isolation';return result};window.recordHeaderPrecision=async()=>{const f=[...document.querySelectorAll('iframe')].find(f=>f.title==='capabilities-ko');f.style.visibility='visible';await f.contentWindow.seedParentResize();f.width=1100;f.style.width='1100px';await f.contentWindow.observeParentResize();const precision=f.contentWindow.headerPrecision();const result={recording:q.get('recording'),scope:'parent-resize-headerprecision5',dpr:devicePixelRatio,originalHashes:HASHES,original:precision.original,rows:precision.rows};const response=await fetch('/evidence/connection-pageintegrationparentresize-windows-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(result)});if(!response.ok)throw Error('Precision evidence POST failed');document.title='Parent resize recorded · original isolation';return result};if(q.get('auto')==='1')window.addEventListener('load',()=>q.get('debug')==='headerprecision'?recordHeaderPrecision():recordParentResize());'''.replace('HASHES',json.dumps(hashes))
(out/f'{prefix}.html').write_text('<!doctype html><meta charset="utf-8"><title>Parent resize · original isolation</title>'+frames+'<script>'+script+'</script>')
